**2. Idempotency** - Use idempotency key in header:

```typescript
export async function POST(req: Request) {
  try {
    const idempotencyKey = req.headers.get('Idempotency-Key');
    if (!idempotencyKey) {
      return Response.json(
        { error: 'Idempotency-Key header required' },
        { status: 400 }
      );
    }

    // Check if this request was already processed
    const existing = await db.idempotentRequest.findUnique({
      where: { key: idempotencyKey }
    });

    if (existing) {
      // Return cached response
      return Response.json(existing.response);
    }

    const body = await req.json();
    const validatedData = createOrderSchema.parse(body);

    const order = await orderService.createOrder(validatedData);

    await paymentQueue.add('process-payment', {
      orderId: order.id,
      amount: order.total,
      userId: validatedData.userId
    });

    const response = { order, message: 'Order created, processing payment' };

    // Store idempotency record
    await db.idempotentRequest.create({
      data: {
        key: idempotencyKey,
        response: response,
        expiresAt: new Date(Date.now() + 24 * 60 * 60 * 1000) // 24 hours
      }
    });

    return Response.json(response);
  } catch (error) {
    // Error handling...
  }
}
```

