**Batch updates** is the right approach! Updating on every message will cause:
- Excessive re-renders
- Janky animations
- Wasted CPU cycles

Recommended strategy:

```typescript
import { useEffect, useRef } from 'react';

function RealtimeChart() {
  const chartRef = useRef<Chart>(null);
  const pendingUpdates = useRef<DataPoint[]>([]);

  useEffect(() => {
    // Batch updates every 100ms
    const interval = setInterval(() => {
      if (pendingUpdates.current.length === 0) return;

      const chart = chartRef.current;
      if (!chart) return;

      // Apply all pending updates at once
      pendingUpdates.current.forEach(point => {
        chart.data.labels.push(point.time);
        chart.data.datasets[0].data.push(point.value);
      });

      // Limit data points to last 1000
      if (chart.data.labels.length > 1000) {
        chart.data.labels = chart.data.labels.slice(-1000);
        chart.data.datasets[0].data = 
          chart.data.datasets[0].data.slice(-1000);
      }

      chart.update('none'); // 'none' disables animation for performance
      pendingUpdates.current = [];
    }, 100); // 10 FPS is smooth enough for dashboards

    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    // WebSocket listener
    const ws = new WebSocket(WEBSOCKET_URL);

    ws.onmessage = (event) => {
      const dataPoint = JSON.parse(event.data);
      pendingUpdates.current.push(dataPoint);
    };

    return () => ws.close();
  }, []);

  // Chart rendering...
}
```

**Key optimizations:**
1. Batch updates every 100ms (10 FPS)
2. Use `update('none')` to disable animations
3. Limit to last 1000 points (sliding window)
4. Collect updates in ref (no state re-renders)

